<script lang="ts">
 import {onMount} from 'svelte';
 import FigureCard from '../_shared/FigureCard.svelte';
 import Timeline from '../_shared/Timeline.svelte';
 import {createLoop,reducedMotion} from '../_shared/loop';
 import {readColors,onThemeChange} from '../_shared/theme';
 import {run,frameAt,recallAtK,QUERY,type makeData,type sweep} from './sim';
 import {exactTopK} from '../../../lib/applied/ann';
 let {mode='exact',title='Find five neighbours'}:{mode?:string;title?:string}=$props();
 let data=$state.raw<ReturnType<typeof makeData>>(),curve=$state.raw<ReturnType<typeof sweep>>(),t=$state(0),playing=$state(false),speed=$state(.5),probe=$state(1),ef=$state(8),qx=$state(.3),cv:HTMLCanvasElement,host:HTMLDivElement,wake=()=>{};
 const result=$derived(data?run(data,mode,[qx,QUERY[1]],probe,ef):null),frame=$derived(result?frameAt(t,result):null),truth=$derived(data?exactTopK(data.pts,[qx,QUERY[1]]).ids:[]);
 $effect(()=>{playing;speed;t;probe;ef;qx;data;curve;wake();});
 onMount(()=>{const worker=new Worker(new URL('./worker.ts',import.meta.url),{type:'module'});worker.onmessage=e=>{if(mode==='tradeoff')curve=e.data;else data=e.data;worker.terminate();wake();};worker.postMessage(mode==='tradeoff'?'sweep':'data');let live=0,last=0;let colors=readColors({point:'--text-muted',ink:'--text',accent:'--accent',forward:'--viz-forward',rule:'--rule',bg:'--bg-raised'});
 const draw=()=>{if(!cv)return;const r=cv.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);cv.width=r.width*dpr;cv.height=r.height*dpr;const c=cv.getContext('2d')!;c.scale(dpr,dpr);const w=r.width,h=r.height;c.clearRect(0,0,w,h);
 if(mode==='tradeoff'){if(!curve)return;const X=(v:number)=>45+(Math.log10(v)-1)/(Math.log10(5000)-1)*(w-65),Y=(v:number)=>h-35-v*(h-65);c.strokeStyle=colors.rule.hex;c.beginPath();c.moveTo(45,20);c.lineTo(45,h-35);c.lineTo(w-15,h-35);c.stroke();c.fillStyle=colors.ink.hex;c.font='12px sans-serif';c.fillText('Recall@10',8,14);c.fillText('Distance calculations (log scale)',45,h-8);[.5,1].forEach(v=>c.fillText(v.toFixed(1),10,Y(v)));[100,1000,5000].forEach(v=>c.fillText(String(v),X(v)-15,h-20));for(const kind of ['ivf','hnsw'] as const){c.strokeStyle=kind==='ivf'?colors.forward.hex:colors.accent.hex;c.fillStyle=c.strokeStyle;c.beginPath();curve.forEach((p,i)=>{const x=X(kind==='ivf'?p.ivfCost:p.hnswCost),y=Y(kind==='ivf'?p.ivfRecall:p.hnswRecall);if(i===0)c.moveTo(x,y);else c.lineTo(x,y);});c.stroke();const p=curve[Math.min(4,Math.floor(t/8*5))],x=X(kind==='ivf'?p.ivfCost:p.hnswCost),y=Y(kind==='ivf'?p.ivfRecall:p.hnswRecall);c.beginPath();c.arc(x,y,5,0,Math.PI*2);c.fill();}return;}
 if(!data||!frame)return;const X=(x:number)=>(x+7)/14*w,Y=(y:number)=>h-(y+7)/14*h;const visited=new Set(frame.seen.map(v=>v.id));if(mode==='hnsw'){c.strokeStyle=colors.rule.hex;for(const id of visited)for(const j of data.graph.edges[frame.layer][id]??[]){c.beginPath();c.moveTo(X(data.pts[id][0]),Y(data.pts[id][1]));c.lineTo(X(data.pts[j][0]),Y(data.pts[j][1]));c.stroke();}}
 data.pts.forEach((p,i)=>{c.fillStyle=visited.has(i)?colors.forward.hex:colors.point.hex;c.globalAlpha=visited.has(i)?.8:.22;c.beginPath();c.arc(X(p[0]),Y(p[1]),1.8,0,Math.PI*2);c.fill();});c.globalAlpha=1;if(mode==='ivf'){c.fillStyle=colors.ink.hex;for(const p of data.ivf.centers)c.fillRect(X(p[0])-3,Y(p[1])-3,6,6);}for(const id of frame.ids){const p=data.pts[id];c.strokeStyle=colors.accent.hex;c.lineWidth=2;c.beginPath();c.arc(X(p[0]),Y(p[1]),6,0,Math.PI*2);c.stroke();}c.strokeStyle=colors.ink.hex;c.beginPath();c.moveTo(X(qx)-6,Y(.4));c.lineTo(X(qx)+6,Y(.4));c.moveTo(X(qx),Y(.4)-6);c.lineTo(X(qx),Y(.4)+6);c.stroke();};
 const loop=createLoop(host,(dt,now)=>{if(playing)live=(live+dt*speed)%8;else live=t;if(now-last>100||!playing){t=live;last=now;draw();}return playing;},{onView:(_,first)=>{if(first&&!reducedMotion())playing=true;}});wake=loop.wake;const off=onThemeChange(()=>{colors=readColors({point:'--text-muted',ink:'--text',accent:'--accent',forward:'--viz-forward',rule:'--rule',bg:'--bg-raised'});wake();});return()=>{worker.terminate();loop.destroy();off();};});
</script>
<div bind:this={host}><FigureCard {title} label="Nearest neighbour search trace" aspect="1.8 / 1" narrowAspect="1 / 1" legend={mode==='tradeoff'?[{label:'IVF',color:'--viz-forward'},{label:'HNSW',color:'--accent'}]:[{label:'Visited',color:'--viz-forward'},{label:'Nearest so far',color:'--accent'}]}>
 <canvas bind:this={cv}></canvas>{#if !data&&!curve}<p class="loading">Building the index in a worker…</p>{/if}
 {#snippet controls()}<Timeline bind:t bind:playing bind:speed duration={8} markers={[{at:0,label:'Begin'},{at:4,label:'Search'},{at:8,label:'Result'}]} onSeek={v=>{t=v;wake();}} onReset={()=>{t=0;wake();}} />{/snippet}
 {#snippet readout()}{#if mode==='tradeoff'&&curve}{@const p=curve[Math.min(4,Math.floor(t/8*5))]}<p>5,000 vectors · 32 coordinates · 200 queries. IVF: {p.ivfCost.toFixed(0)} comparisons, {(100*p.ivfRecall).toFixed(1)}% recall. HNSW: {p.hnswCost.toFixed(0)} comparisons, {(100*p.hnswRecall).toFixed(1)}% recall. Exact search: 5,000 comparisons, 100% recall.</p>{:else if result&&frame}<p>{frame.count} of {result.trace.length} point-distance calculations shown{mode==='ivf'?' + 16 centroid comparisons':''}. {mode==='hnsw'?`Layer ${frame.layer}.`:''} Current recall: {frame.ids.filter(id=>truth.includes(id)).length}/5 = {(100*recallAtK(frame.ids,truth)).toFixed(0)}%. The + marks the query.</p>{/if}{/snippet}
 {#snippet footer()}{#if mode!=='tradeoff'}<div class="inputs"><label>Query horizontal position <input type="range" min="-4" max="4" step=".1" bind:value={qx} oninput={()=>{t=0;wake();}} /></label>{#if mode==='ivf'}<label>Buckets searched: {probe}<input type="range" min="1" max="16" step="1" bind:value={probe} oninput={()=>{t=0;wake();}} /></label>{:else if mode==='hnsw'}<label>Candidate budget (ef): {ef}<input type="range" min="8" max="64" step="8" bind:value={ef} oninput={()=>{t=0;wake();}} /></label>{/if}</div>{/if}{/snippet}
</FigureCard></div>
<style>.loading{position:absolute;inset:30% 1rem auto;text-align:center}.inputs{display:flex;flex-wrap:wrap;gap:1rem;padding:1rem}.inputs label{display:grid;gap:.4rem;flex:1;min-width:180px}input{accent-color:var(--accent)}</style>
